Mkt3L10n.socialAppDashboard = {
  Social_Dashboard: "ソーシャルダッシュボード",
  Date_of_Activity: "アクティビティ日",
  Last_Updated: "最終更新日",
  Social_Funnel: "ソーシャルファネル",
  Audience: "対象ユーザ <span style='font-weight:normal'> (プロファイル総数: {0})</span>",
  Share_Metrics: "指標の共有",
  Share_Rate_percentage: "<div style=\"font-weight: bold\">共有率:</div><p>訪問者のうち共有 (シェア) を行った割合。</p><br/><div style=\"font-weight: bold\">クリックバック率:</div> <p>共有ごとのクリック数。</p><br/><div style=\"font-weight: bold\">ソーシャルリフト値:</div><p>ソーシャルサイト経由の訪問 (共有された URL からのアクセス) と経由していない訪問 (他のソースからのアクセス) の割合をパーセントで表した比率。</p><br/>",
  Total_Profiles_number_users_who_signed_social_network: "<div style=\"font-weight: bold\">プロファイル総数:</div><p>ソーシャルアプリを使ってソーシャルネットワークにサインイン (インタラクション) したユーザー数。</p><br/> <div style=\"font-weight: bold\">影響者:</div><p>共有リンクから少なくとも 1 人の参照による訪問者をもたらしたユーザー数。</p><br/><div style=\"font-weight: bold\">ソーシャルリーチ:</div><p>キャンペーンにおけるすべてのユーザーの接続総数。 ソーシャルネットワークユーザーには共有時にその友達の数を表示し、メールユーザーにはメール受信者数を表示します。</p><br/><div style=\"font-weight: bold\">ソーシャルインプレッション数:</div><p>キャンペーンからメッセージが共有された回数。 これは各共有者のソーシャルリーチに共有回数を乗算し、共有を行ったすべてのユーザーのソーシャルインプレッション数を足すと最終的なスコアが生成されます。</p><br/>",
  Visits_number_sessions_Campaign: "<div style=\"font-weight: bold\">訪問者数:</div><p>一定期間中にサイトにユーザーがアクセスした回数 (訪問者ごとに開始される一意のセッション)。 いったんサイトを離れ 30 分以内に再度訪問したユーザーは、最初のアクセスの一部とみなされます。 30 分以上の時間差でサイトを訪問したり、ブラウザを閉じて再起動したユーザによるアクセスは新規セッション/アクセスになります。</p><br/><div style=\"font-weight: bold\">キャンペーン訪問者数:</div><p>サイトのすべてのキャンペーンへのアクセス者の数。 同一キャンペーンの 1 ページに配置された複数のプレースメントにアクセスした場合は、キャンペーン訪問者数は 1 とみなされます。 同一キャンペーンの複数ページに配置されたプレースメントにアクセスした場合もまた、キャンペーン訪問者数は 1 とみなされます。</p><br/><div style=\"font-weight: bold\">インタラクション数:</div><p>ユーザーが行ったソーシャルアクションの回数 (投票、評価、共有、コメントの投稿、オファーへのサインアップ、動画の共有など)。 </p><br/><div style=\"font-weight: bold\">共有数:</div><p>ユーザーがソーシャルネットワークでメッセージを共有した回数。</p><br/><div style=\"font-weight: bold\">結果クリック数:</div><p>キャンペーンからのリンクの共有によって、ページが表示された回数。</p><br/><div style=\"font-weight: bold\">コンバージョン:</div><p>サイトに実装されているコンバージョン スクリプトの定義に基づき、ユーザーが特定のアクション (製品の購入など) を行った回数。 \"登録\" (あるいは共有リンクをたどってサイトを閲覧し、最初にインタラクションを行ったユーザー) はコンバージョン スクリプトが実装されていない場合のデフォルトのコンバージョン イベントです。</p><br/>",
  Data_will_be_updated_within_24_hours: "データは 24 時間以内に更新されます"
};

