  Ad_bridge_partner_ad_message_linkedin_reauthorize: "2018 年第 1 四半期リリースで、LinkedIn Matched Audience コネクターをアップグレードしました。LinkedIn Matched Audience Launchpoint サービスを更新して、新しいコネクターを使用してください。<br/><br/><a href='{0}' target='_blank'>詳細</a>",
